/// Task priority, matching the Almacén CHECK constraint.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Priority {
    Alta,
    Media,
    Baja,
}

/// Task status, matching the Almacén CHECK constraint.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum TaskStatus {
    Pendiente,
    Completada,
    Cancelada,
}

// ---------------------------------------------------------------------------
// Storage DTOs (Tasks, Events, Groups)
// ---------------------------------------------------------------------------

/// IPC-level representation of a Task. Dates are ISO 8601 strings so the
/// IPC layer does not depend on the `storage` crate yet.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct StorageTaskDto {
    pub id: i64,
    pub title: String,
    pub priority: Priority,
    pub status: TaskStatus,
    /// ISO 8601 timestamp with timezone offset.
    pub created_at: String,
    /// ISO 8601 timestamp with timezone offset; `None` when the Task has
    /// no deadline.
    pub deadline: Option<String>,
    pub group_id: Option<i64>,
}

/// Patch used by `storage.update_task`. Any field left as `None` is not
/// modified. Nullable domain fields (deadline, group_id) use the
/// double-wrapped `Option<Option<T>>` pattern to distinguish "don't
/// touch" from "set to NULL".
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct StorageTaskPatch {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub priority: Option<Priority>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub status: Option<TaskStatus>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub deadline: Option<Option<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub group_id: Option<Option<i64>>,
}

/// IPC-level representation of an Event.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct StorageEventDto {
    pub id: i64,
    pub title: String,
    /// `YYYY-MM-DD`.
    pub start_date: String,
    /// `HH:MM`.
    pub start_time: String,
    pub duration_minutes: Option<u32>,
    pub group_id: Option<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct StorageEventPatch {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub start_date: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub start_time: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub duration_minutes: Option<Option<u32>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub group_id: Option<Option<i64>>,
}

/// IPC-level representation of a Group.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct StorageGroupDto {
    pub id: i64,
    pub name: String,
    /// Hex color code `#RRGGBB`.
    pub color: String,
}

