// ---------------------------------------------------------------------------
// Tests — minimal smoke checks wiring the types together. The full
// property-based round-trip test lives in task 2.2.
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn user_message_envelope_round_trips_through_json() {
        let payload = UserMessagePayload {
            text: "crea una tarea urgente para mañana".to_string(),
        };
        let envelope = Envelope::new(Kind::Request, MessageType::UserMessage, &payload)
            .expect("payload serializes");

        let json = serde_json::to_string(&envelope).expect("envelope serializes");
        let decoded: Envelope = serde_json::from_str(&json).expect("envelope deserializes");

        assert_eq!(decoded, envelope);
        assert_eq!(decoded.v, PROTOCOL_VERSION);
        assert_eq!(decoded.kind, Kind::Request);
        assert_eq!(decoded.message_type, MessageType::UserMessage);
        let decoded_payload = decoded
            .payload_as::<UserMessagePayload>()
            .expect("payload decodes")
            .expect("payload present");
        assert_eq!(decoded_payload, payload);
    }

    #[test]
    fn error_response_envelope_round_trips_without_payload() {
        let request_id = Uuid::new_v4();
        let envelope = Envelope::new_empty(Kind::Response, MessageType::StorageCreateGroup)
            .with_ref(request_id)
            .with_error(StorageError::new(
                "GROUP_NAME_NOT_UNIQUE",
                "Ya existe un Grupo llamado 'trabajo'",
            ));

        let json = serde_json::to_string(&envelope).expect("envelope serializes");
        let decoded: Envelope = serde_json::from_str(&json).expect("envelope deserializes");

        assert_eq!(decoded, envelope);
        assert!(decoded.payload.is_none());
        assert_eq!(decoded.ref_id, Some(request_id));
        assert_eq!(decoded.error.as_ref().unwrap().code, "GROUP_NAME_NOT_UNIQUE");
    }

    #[test]
    fn storage_task_type_serializes_with_dotted_notation() {
        let mt = MessageType::StorageCreateTask;
        let json = serde_json::to_string(&mt).expect("type serializes");
        assert_eq!(json, "\"storage.create_task\"");
    }

    #[test]
    fn unsupported_protocol_version_fails_to_deserialize() {
        let raw = serde_json::json!({
            "v": 2,
            "id": "00000000-0000-4000-8000-000000000000",
            "kind": "request",
            "type": "user_message",
            "payload": { "text": "hola" }
        });

        let result: Result<Envelope, _> = serde_json::from_value(raw);
        let err = result.expect_err("v=2 must be rejected");
        let message = err.to_string();
        assert!(
            message.contains("unsupported IPC protocol version"),
            "unexpected error message: {message}"
        );
    }

    #[test]
    fn model_provider_serializes_lowercase() {
        let json = serde_json::to_string(&ModelProvider::Remote).expect("serializes");
        assert_eq!(json, "\"remote\"");
    }

    #[test]
    fn priority_serializes_in_spanish() {
        let json = serde_json::to_string(&Priority::Alta).expect("serializes");
        assert_eq!(json, "\"alta\"");
    }

    #[test]
    fn task_status_serializes_in_spanish() {
        let json = serde_json::to_string(&TaskStatus::Pendiente).expect("serializes");
        assert_eq!(json, "\"pendiente\"");
    }

    #[test]
    fn storage_task_dto_round_trips() {
        let dto = StorageTaskDto {
            id: 42,
            title: "Comprar pan".to_string(),
            priority: Priority::Alta,
            status: TaskStatus::Pendiente,
            created_at: "2025-02-14T10:12:00+01:00".to_string(),
            deadline: Some("2025-02-15T09:00:00+01:00".to_string()),
            group_id: Some(3),
        };
        let json = serde_json::to_string(&dto).expect("dto serializes");
        let decoded: StorageTaskDto = serde_json::from_str(&json).expect("dto deserializes");
        assert_eq!(dto, decoded);
    }
}
